    12→async function PropertyDetailContent({ propertyId }: { propertyId: string }) {
    13→  const result = await getPropertyDetailAction(propertyId);
    14→
    15→  if (result.error || !result.property) {
    16→    if (result.error?.includes("n'existe plus")) {
    17→      notFound();
    18→    }
    19→
    20→    return (
    21→      <div className="container mx-auto px-4 py-8">
