    23→          <h1 className="text-destructive mb-4 text-2xl font-bold">Erreur</h1>
    24→          <p className="text-muted-foreground mb-4">
    25→            {result.error ?? "Une erreur est survenue"}
    26→          </p>
    27→        </div>
    28→      </div>
    29→    );
    30→  }
    31→
    32→  return <PropertyDetailView property={result.property} />;
    33→}
    34→
    35→export default async function PropertyDetailPage({
    36→  params,
    37→}: PropertyDetailPageProps) {
    38→  const { id } = await params;
    39→
    40→  return (
    41→    <Suspense fallback={<PropertyDetailSkeleton />}>
    42→      <PropertyDetailContent propertyId={id} />
    43→    </Suspense>
    44→  );
    45→}
    46→
    47→// Generate metadata for SEO
    48→export async function generateMetadata({ params }: PropertyDetailPageProps) {
    49→  const { id } = await params;
    50→
    51→  try {
    52→    const result = await getPropertyDetailAction(id);
    53→
    54→    if (!result.property) {
    55→      return {
    56→        title: "Bien non trouvé - ChooseWisely",
    57→      };
    58→    }
    59→
    60→    const { property } = result;
    61→    const priceFormatted = new Intl.NumberFormat("fr-FR", {
    62→      style: "currency",
    63→      currency: "EUR",
    64→      maximumFractionDigits: 0,
    65→    }).format(property.price);
    66→
    67→    return {
    68→      title: `${property.title} - ${priceFormatted} - ${property.city} | ChooseWisely`,
    69→      description:
    70→        property.description ??
    71→        `${property.category} de ${property.surface}m² à ${property.city}`,
    72→    };
    73→  } catch (error) {
    74→    // Fallback metadata if API call fails during build/SSG
    75→    logger.debug("Failed to generate metadata for property:", id, error);
    76→    return {
    77→      title: "Détail du bien - ChooseWisely",
    78→      description:
    79→        "Consultez les détails de ce bien immobilier sur ChooseWisely",
    80→    };
    81→  }
    82→}
