     7→import type { LayoutParams, PageParams } from "@/types/next";
     8→import type { Metadata } from "next";
     9→import { headers } from "next/headers";
    10→import { OrgList } from "./(navigation)/_navigation/org-list";
    11→import { InjectCurrentOrgStore } from "./use-current-org";
    12→
    13→export async function generateMetadata(
    14→  props: PageParams<{ orgSlug: string }>,
    15→): Promise<Metadata> {
    16→  const params = await props.params;
    17→  return orgMetadata(params.orgSlug);
    18→}
    19→
    20→export default async function RouteLayout(
    21→  props: LayoutParams<{ orgSlug: string }>,
    22→) {
    23→  const params = await props.params;
    24→
    25→  const org = await getCurrentOrg();
    26→
    27→  // The user try to go to another organization, we must sync with the URL
    28→  if (org?.slug !== params.orgSlug) {
    29→    const user = await getRequiredUser();
    30→    const org = await prisma.organization.findFirst({
    31→      where: {
    32→        OR: [
    33→          {
    34→            slug: params.orgSlug,
    35→          },
    36→          {
    37→            id: params.orgSlug,
    38→          },
    39→        ],
    40→        members: {
    41→          some: {
    42→            userId: user.id,
    43→          },
    44→        },
    45→      },
    46→      select: {
    47→        id: true,
    48→      },
    49→    });
    50→
    51→    // If we can't find the organization, we must show the org list
    52→    if (!org) {
    53→      return <OrgList />;
    54→    }
    55→
    56→    await auth.api.setActiveOrganization({
    57→      headers: await headers(),
    58→      body: {
    59→        organizationId: org.id,
    60→      },
    61→    });
    62→
    63→    return <RefreshPageOrganization />;
    64→  }
    65→
    66→  return (
    67→    <InjectCurrentOrgStore
    68→      org={{
    69→        id: org.id,
    70→        slug: org.slug,
    71→        name: org.name,
    72→        image: org.logo ?? null,
    73→        subscription: org.subscription,
    74→      }}
    75→    >
    76→      {props.children}
    77→    </InjectCurrentOrgStore>
    78→  );
    79→}
